select.where:
del_flag = '0'
and is_merged = '0'

    and title like concat('%', #{title}, '%')


and (title like concat('%', #{keyword}, '%') or summary like concat('%', #{keyword}, '%'))


    and source_type = #{sourceType}


    and is_favorite = #{isFavorite}


    and create_time >= #{params.beginTime}


    and create_time <= #{params.endTime}



    and create_by = #{createBy}



    and exists (
    select 1 from huiyi_meeting_folder_rel r
    where r.meeting_id = huiyi_meeting.meeting_id and r.folder_id = #{folderId}
    )



    and not exists (
    select 1 from huiyi_meeting_folder_rel r2
    where r2.meeting_id = huiyi_meeting.meeting_id and r2.folder_id = #{excludeFolderId}
    )


    and status = #{status}

mapper.update:
update huiyi_meeting
title = #{title}, source_type = #{sourceType}, audio_path = #{audioPath}, duration = #{duration}, status = #{status}, is_favorite = #{isFavorite}, update_by = #{updateBy}, summary = #{summary}, update_time = sysdate()
where meeting_id = #{meetingId}

update huiyi_meeting set is_merged = '1', update_time = sysdate()
where meeting_id in

    #{meetingId}

update huiyi_meeting
record_status = #{recordStatus}, record_start_time = #{recordStartTime}, record_end_time = #{recordEndTime}, audio_path = #{audioPath}, duration = #{duration}, update_time = sysdate()
where meeting_id = #{meetingId}
